        <div class="coupon-reminder-options"><label class="coupon-check"><input v-model="editor.draft.reminder.enabled" type="checkbox" /> 到期前一个月提醒</label><label class="coupon-check"><input v-model="editor.draft.reminder.sevenDays" type="checkbox" :disabled="!editor.draft.reminder.enabled" /> 提前 7 天再提醒一次</label><div v-if="editor.draft.reminder.enabled" class="coupon-recipients"><span>提醒谁</span><label v-for="recipient in recipientOptions" :key="recipient.id" class="coupon-check"><input v-model="editor.draft.reminder.recipients" type="checkbox" :value="recipient.id" /> {{ recipient.label }}</label></div><p class="coupon-help">仅已购、日期已确认且未使用的券会进入提醒。想去的收藏不催你消费。</p></div>
        <p v-if="editorError" class="coupon-error" role="alert">{{ editorError }} <button type="button" class="coupon-text" @click="pauseEditor">保留草稿并收起</button></p>
        <div v-if="discardRequested" class="coupon-discard" role="alert"><p>这次修改尚未保存。</p><button type="button" class="coupon-secondary" @click="discardRequested = false">继续整理</button><button type="button" class="coupon-text" @click="pauseEditor">保留草稿</button><button type="button" class="coupon-danger" @click="finishEditor">放弃修改</button></div>
      </fieldset><footer class="coupon-dialog-footer"><button type="button" class="coupon-secondary" :disabled="!!busy" @click="closeEditor">取消</button><button class="coupon-primary" :disabled="!!busy">{{ busy === 'save' ? '保存中…' : '收进券册' }}</button></footer></form>
    </dialog>

    <dialog v-if="selected" ref="detailDialog" class="coupon-dialog coupon-detail" @cancel.prevent="!busy && closeDetails()"><header class="coupon-dialog-heading"><div><p class="eyebrow">OUR LITTLE GETAWAYS</p><h2>一张券，一份期待</h2></div><button class="coupon-icon" aria-label="关闭券详情" :disabled="!!busy" @click="closeDetails"><i class="ph ph-x"></i></button></header><div class="coupon-dialog-body"><CouponCard :coupon="selected" :today="today" @open="editCoupon(selected)" /><dl class="coupon-detail-grid"><div><dt>现在的状态</dt><dd>{{ stateLabel(couponState(selected, today)) }}</dd></div><div><dt>谁收下的</dt><dd>{{ selected.author || '我们' }}</dd></div><div><dt>使用有效期至</dt><dd>{{ dateText(selected.expiresOn) }}</dd></div><div><dt>预约截止</dt><dd>{{ selected.bookingDeadline ? dateText(selected.bookingDeadline) : '未提供' }}</dd></div><div v-if="selected.advertisedPrice"><dt>海报价格</dt><dd>¥{{ selected.advertisedPrice }}</dd></div><div v-if="selected.paidPrice"><dt>实际支付</dt><dd>¥{{ selected.paidPrice }}</dd></div><div v-if="selected.plannedOn"><dt>计划使用</dt><dd>{{ dateText(selected.plannedOn) }}</dd></div><div><dt>到期提醒</dt><dd>{{ reminderDescription(selected) }}</dd></div></dl><div v-if="selected.rules" class="coupon-detail-copy"><h3>使用规则</h3><p>{{ selected.rules }}</p></div><div v-if="selected.notes" class="coupon-detail-copy"><h3>想记下的话</h3><p>{{ selected.notes }}</p></div><div class="coupon-private-files"><h3><i class="ph ph-lock-key" aria-hidden="true"></i> 原始截图</h3><p class="coupon-help">登录后按需查看，券码不会出现在票面或提醒消息中。</p><button v-for="(attachment, index) in selected.attachments || []" :key="attachment.objectKey" class="coupon-secondary" @click="viewAttachment(attachment)"><i class="ph ph-file-image" aria-hidden="true"></i> 查看截图 {{ index + 1 }}</button><p v-if="!selected.attachments?.length" class="coupon-help">这张券还没有附上截图。</p></div><p v-if="selectedReminder" class="coupon-help">提醒状态：{{ selectedReminder }}</p><div v-if="arranging" class="coupon-arrange"><label>计划哪天去<input v-model="planDate" type="date" /></label><button class="coupon-primary" :disabled="busy || !planDate" @click="savePlan">放进日历</button><button class="coupon-text" @click="arranging = false">取消</button></div><p v-if="detailError" class="coupon-error" role="alert">{{ detailError }}</p><details class="coupon-more"><summary>更多操作</summary><div class="coupon-inline-actions"><button v-if="selected.status !== 'refunded'" class="coupon-secondary" :disabled="busy || readOnly" @click="changeStatus('refunded')">标记已退款</button><button v-if="['used', 'refunded'].includes(selected.status)" class="coupon-secondary" :disabled="busy || readOnly" @click="changeStatus('unused')">恢复待使用</button><button class="coupon-danger" :disabled="busy || readOnly" @click="deleteCoupon">移到回收站</button></div></details></div><footer class="coupon-dialog-footer"><button class="coupon-secondary" :disabled="busy || readOnly" @click="editCoupon(selected)">编辑</button><button v-if="['unused', 'booked'].includes(selected.status)" class="coupon-secondary" :disabled="busy || readOnly" @click="arranging = !arranging">安排一下</button><button v-if="['unused', 'booked'].includes(selected.status)" class="coupon-primary" :disabled="busy || readOnly" @click="changeStatus('used')">标记已用</button><button v-if="selected.status === 'wish'" class="coupon-primary" :disabled="busy || readOnly" @click="changeStatus('unused')">已经买下了</button></footer></dialog>

    <dialog v-if="imageViewer" ref="imageDialog" class="coupon-dialog coupon-original" @cancel.prevent="closeImage"><header class="coupon-dialog-heading"><h2>原始截图</h2><button class="coupon-icon" aria-label="关闭原始截图" @click="closeImage"><i class="ph ph-x"></i></button></header><div class="coupon-original-body"><p v-if="imageViewer.loading" role="status">正在读取私有截图…</p><p v-if="imageViewer.error" class="coupon-error" role="alert">{{ imageViewer.error }}<button class="coupon-secondary" @click="viewAttachment(imageViewer.attachment)">重试</button></p><img v-if="imageViewer.url" :src="imageViewer.url" alt="券的原始截图" /></div></dialog>
    <CouponImageEditor v-if="processingFile" :file="processingFile.file" @close="processingFile = null" @save="replaceFile" />
  </main>
</template>

<script setup>
import { computed, inject, nextTick, onActivated, onBeforeUnmount, onDeactivated, onMounted, ref, watch } from 'vue';
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router';
import CouponCard from '../features/coupons/CouponCard.vue';
import CouponImageEditor from '../features/coupons/CouponImageEditor.vue';
import { activeDeadline, couponSort, couponState, createCoupon, dayKey, isCouponDate, normalizeCoupon } from '../features/coupons/model.js';
import { couponRequest, dateText, daysBetween, readCouponImage, stateLabel, uploadCouponFile } from '../features/coupons/client.js';
import '../features/coupons/coupons.css';
const familyData = inject('familyData'), revision = inject('familyRevision'), commitFamily = inject('commitFamily'), trashItem = inject('trashItem');
const currentMember = inject('currentMember', ref('Aosen')), readOnly = inject('isDemoMode', ref(false));
const route = useRoute(), router = useRouter();
const clock = ref(new Date()), today = computed(() => dayKey(clock.value)), timer = setInterval(() => { clock.value = new Date(); }, 30000);
const coupons = computed(() => (familyData.value.coupons || []).map(normalizeCoupon));
const filter = ref('pending'), query = ref(''), listView = ref(false), busy = ref(''), error = ref(''), notice = ref(''), undo = ref(null);
const tabs = [{ id: 'pending', label: '待使用' }, { id: 'wish', label: '想去' }, { id: 'archive', label: '归档' }];
const filtered = computed(() => coupons.value.filter(c => { const state = couponState(c, today.value); return (filter.value === 'pending' ? ['unused', 'booked'].includes(state) : filter.value === 'wish' ? state === 'wish' : ['used', 'refunded', 'expired'].includes(state)) && `${c.title} ${c.merchant} ${c.location} ${c.summary}`.toLowerCase().includes(query.value.trim().toLowerCase()); }).sort(couponSort));
const groups = computed(() => { if (filter.value !== 'archive') return [{ year: '', items: filtered.value }]; const map = new Map(); for (const coupon of filtered.value) { const year = (coupon.usedAt || coupon.updatedAt || coupon.expiresOn || coupon.createdAt || '').slice(0, 4) || '收好的时光'; if (!map.has(year)) map.set(year, []); map.get(year).push(coupon); } return [...map].sort(([a], [b]) => b.localeCompare(a)).map(([year, items]) => ({ year, items })); });
const pendingCount = computed(() => coupons.value.filter(c => ['unused', 'booked'].includes(couponState(c, today.value))).length);
const dueCount = computed(() => coupons.value.filter(c => { const days = daysBetween(today.value, activeDeadline(c)?.date); return ['unused', 'booked'].includes(couponState(c, today.value)) && c.deadlineConfirmed && days !== null && days >= 0 && days <= 31; }).length);
const missingDates = computed(() => filtered.value.filter(c => !activeDeadline(c) || !c.deadlineConfirmed).length);
const editor = ref(null), editorVisible = ref(false), editorDialog = ref(null), editorError = ref(''), discardRequested = ref(false), files = ref([]), evidence = ref({}), warnings = ref([]), progress = ref(''), recognitionMessage = ref(''), processingFile = ref(null), recognitionSelection = ref([]);
let initialEditor = '', detailVersion, detailSnapshot;
const duplicates = computed(() => editor.value?.draft.title?.trim() ? coupons.value.filter(c => c.id !== editor.value.draft.id && (c.title === editor.value.draft.title || c.merchant && c.merchant === editor.value.draft.merchant)) : []);
const selectedId = ref(''), detailDialog = ref(null), selected = computed(() => coupons.value.find(c => c.id === selectedId.value)), detailError = ref(''), arranging = ref(false), planDate = ref('');
const imageViewer = ref(null), imageDialog = ref(null); let imageRequest = 0;
const reminders = ref(null), loadingReminders = ref(false), reminderError = ref(''), simulationDate = ref(dayKey());
const isPreview = import.meta.env.DEV && import.meta.env.VITE_PERSONAL_PREVIEW === '1';
const recipientOptions = computed(() => reminders.value?.recipients?.length ? reminders.value.recipients : [{ id: 'aosen', label: 'Aosen（渠道待配置）' }, { id: 'xiaoyue', label: '小悦（渠道待配置）' }]);
const reminderSummary = computed(() => isPreview ? '本机演练' : !reminders.value ? '正在读取配置' : !reminders.value.configured ? '接收渠道待配置' : !reminders.value.schedulerConfigured ? '定时任务待验收' : reminders.value.schedulerHealthy ? '最近定时检查正常' : '定时检查需核对');
const selectedReminder = computed(() => { const row = reminders.value?.statuses?.find(x => x.couponId === selectedId.value); if (!row) return ''; return row.label || ({ pending: '等待发送', accepted: '平台已接收', sent: '平台发送成功', delivered: '平台发送成功', failed: '发送失败，将按规则重试', unknown: '结果待核实', skipped: '本次未发送', simulated: '本机演练完成' })[row.status] || row.status; });
const clone = value => JSON.parse(JSON.stringify(value));
const formatTime = value => { const date = new Date(value); return Number.isNaN(date.getTime()) ? '尚未执行' : date.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' }); };
function reminderDescription(coupon) { if (coupon.status === 'wish') return '想去的收藏暂不提醒'; if (['used', 'refunded'].includes(coupon.status)) return '已停止后续提醒'; if (!coupon.deadlineConfirmed || !activeDeadline(coupon)) return '补充并核对日期后可提醒'; if (!coupon.reminder.enabled) return '未开启'; return `提前一个月${coupon.reminder.sevenDays ? '，及提前 7 天' : ''}`; }
async function loadReminders() { loadingReminders.value = true; reminderError.value = ''; try { reminders.value = await couponRequest('/api/coupon-reminders'); } catch (e) { reminderError.value = e.message; } finally { loadingReminders.value = false; } }
async function simulateReminder() { loadingReminders.value = true; reminderError.value = ''; try { const result = await couponRequest('/api/coupon-reminders', { action: 'simulate', date: simulationDate.value }); notice.value = `本机检查完成：${result.result?.eligible || 0} 项符合提醒条件，模拟 ${result.result?.batches || 0} 条汇总；没有发送微信消息。`; await loadReminders(); } catch (e) { reminderError.value = e.message; } finally { loadingReminders.value = false; } }
async function newCoupon() { if (readOnly.value) return; if (editor.value) return resumeEditor(); await closeDetails(); editor.value = { isNew: true, draft: createCoupon(currentMember.value), snapshot: clone(familyData.value), revision: revision.value }; evidence.value = {}; warnings.value = []; recognitionMessage.value = ''; initialEditor = JSON.stringify(editor.value.draft); await resumeEditor(); }
async function editCoupon(coupon) { if (readOnly.value) return; if (editor.value) return resumeEditor(); await closeDetails(); editor.value = { isNew: false, draft: clone(normalizeCoupon(coupon)), snapshot: clone(familyData.value), revision: revision.value }; initialEditor = JSON.stringify(editor.value.draft); recognitionSelection.value = editor.value.draft.attachments.slice(0, 3).map(a => a.objectKey); evidence.value = {}; warnings.value = []; recognitionMessage.value = ''; await resumeEditor(); }
async function resumeEditor() { editorVisible.value = true; discardRequested.value = false; await nextTick(); if (!editorDialog.value.open) editorDialog.value.showModal(); }
function pauseEditor() { editorDialog.value?.close(); editorVisible.value = false; discardRequested.value = false; }
function closeEditor() { if (busy.value) return; if (JSON.stringify(editor.value?.draft) !== initialEditor || files.value.length) { discardRequested.value = true; return; } finishEditor(); }
function releaseFiles() { files.value.forEach(file => URL.revokeObjectURL(file.url)); files.value = []; recognitionSelection.value = []; }
function finishEditor() { editorDialog.value?.close(); editor.value = null; editorVisible.value = false; discardRequested.value = false; editorError.value = ''; progress.value = ''; evidence.value = {}; warnings.value = []; releaseFiles(); }
function selectFiles(event) { editorError.value = ''; for (const file of Array.from(event.target.files || [])) { if (files.value.length + editor.value.draft.attachments.length >= 6) { editorError.value = '每张券最多附上 6 张截图。'; break; } if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 4 * 1024 * 1024) { editorError.value = '请选择 4 MB 以内的 JPG、PNG 或 WebP 截图。'; continue; } const id = crypto.randomUUID(); files.value.push({ id, file, url: URL.createObjectURL(file), attachment: null, error: '' }); if (recognitionSelection.value.length < 3) recognitionSelection.value.push(id); } event.target.value = ''; }
function removeFile(id) { recognitionSelection.value = recognitionSelection.value.filter(value => value !== id); const index = files.value.findIndex(file => file.id === id); if (index >= 0) { URL.revokeObjectURL(files.value[index].url); files.value.splice(index, 1); } }
function replaceFile(file) { const target = processingFile.value; if (!target) return; if (file.size > 4 * 1024 * 1024) { editorError.value = '处理后的图片超过 4 MB，请再裁剪一些。'; processingFile.value = null; return; } URL.revokeObjectURL(target.url); target.file = file; target.url = URL.createObjectURL(file); target.attachment = null; target.error = ''; processingFile.value = null; }
async function uploadFiles() { for (let index = 0; index < files.value.length; index++) { const item = files.value[index]; if (item.attachment) continue; progress.value = `正在保存截图 ${index + 1} / ${files.value.length}…`; item.error = ''; try { item.attachment = await uploadCouponFile(item.file); } catch (e) { item.error = e.message; throw e; } } return [...editor.value.draft.attachments, ...files.value.map(item => item.attachment).filter(Boolean)]; }
async function recognize() { if (busy.value) return; busy.value = 'recognize'; editorError.value = ''; try { if (!recognitionSelection.value.length || recognitionSelection.value.length > 3) throw Error('请勾选 1 到 3 张截图用于这次识别。'); await uploadFiles(); const keys = [...editor.value.draft.attachments.filter(a => recognitionSelection.value.includes(a.objectKey)).map(a => a.objectKey), ...files.value.filter(f => recognitionSelection.value.includes(f.id)).map(f => f.attachment.objectKey)]; if (!keys.length) throw Error('请重新选择用于识别的截图。'); progress.value = '正在整理截图中的信息…'; const result = await couponRequest('/api/coupon-recognize', { attachmentKeys: keys, allowExternal: true }); const draft = result.draft || {}; for (const key of ['title', 'merchant', 'location', 'category', 'summary', 'expiresOn', 'bookingDeadline', 'advertisedPrice', 'paidPrice', 'rules']) if (typeof draft[key] === 'string' && draft[key]) editor.value.draft[key] = draft[key]; editor.value.draft.deadlineConfirmed = false; evidence.value = result.evidence || {}; warnings.value = result.warnings || []; recognitionMessage.value = result.source === 'preview' ? '这是本机演示识别结果，请核对信息后保存；没有调用外部识别服务。' : '已整理出初稿，请重点核对购买状态和有效日期。'; } catch (e) { editorError.value = e.message + ' 图片与输入仍保留，可以重试或手动填写。'; } finally { progress.value = ''; busy.value = ''; } }
async function saveEditor() { if (busy.value || readOnly.value) return; busy.value = 'save'; editorError.value = ''; try { const d = editor.value.draft; if (!d.title?.trim()) throw Error('请给这张券取一个名字。'); for (const key of ['expiresOn', 'bookingDeadline', 'plannedOn']) if (d[key] && !isCouponDate(d[key])) throw Error('请填写有效日期。'); if (d.plannedOn && d.expiresOn && d.plannedOn > d.expiresOn) throw Error('计划使用日期已超过有效期，请重新安排。'); if (d.reminder.enabled && !d.reminder.recipients.length) throw Error('请选择至少一位提醒接收人，或关闭提醒。'); const saved = normalizeCoupon({ ...clone(d), title: d.title.trim(), merchant: d.merchant || d.title.trim(), attachments: await uploadFiles(), updatedAt: new Date().toISOString() }); const state = editor.value; await commitFamily(data => { data.coupons ||= []; const index = data.coupons.findIndex(c => c.id === saved.id); if (!state.isNew && index < 0) throw Error('这张券已被移除，请先检查最新记录。'); if (index >= 0) data.coupons[index] = saved; else data.coupons.unshift(saved); }, { label: '券册已保存', snapshot: state.snapshot, revision: state.revision }); finishEditor(); filter.value = saved.status === 'wish' ? 'wish' : ['used', 'refunded', 'expired'].includes(couponState(saved, today.value)) ? 'archive' : 'pending'; query.value = ''; notice.value = saved.deadlineConfirmed && activeDeadline(saved) && saved.status !== 'wish' && saved.reminder.enabled ? '已收进券册，并记录了到期前一个月的提醒设置。' : '已收进券册。' + (!saved.deadlineConfirmed && saved.status !== 'wish' ? '补充并核对日期后可以提醒。' : ''); undo.value = null; await router.replace({ path: '/life/coupons', query: {} }); } catch (e) { editorError.value = e.message; } finally { busy.value = ''; progress.value = ''; } }
async function openDetails(coupon, updateUrl = true) { if (editorVisible.value) pauseEditor(); selectedId.value = coupon.id; detailError.value = ''; arranging.value = false; planDate.value = coupon.plannedOn || ''; detailSnapshot = clone(familyData.value); detailVersion = revision.value; await nextTick(); if (detailDialog.value && !detailDialog.value.open) detailDialog.value.showModal(); if (updateUrl) await router.replace({ path: '/life/coupons', query: { coupon: coupon.id } }); }
async function closeDetails() { detailDialog.value?.close(); selectedId.value = ''; arranging.value = false; if (route.query.coupon) await router.replace({ path: '/life/coupons', query: {} }); }
async function updateSelected(mutator, label) { if (busy.value || readOnly.value || !selected.value) return false; busy.value = 'update'; detailError.value = ''; const id = selectedId.value; try { await commitFamily(data => { const item = data.coupons?.find(c => c.id === id); if (!item) throw Error('这张券已被移除，请刷新。'); mutator(item); item.updatedAt = new Date().toISOString(); }, { label, snapshot: detailSnapshot, revision: detailVersion }); detailSnapshot = clone(familyData.value); detailVersion = revision.value; return true; } catch (e) { detailError.value = e.message; return false; } finally { busy.value = ''; } }
async function changeStatus(status) { const before = clone(selected.value), id = before.id; if (await updateSelected(item => { item.status = status; if (status === 'used') item.usedAt = new Date().toISOString(); }, '已更新券的状态')) { const expected = clone(selected.value); notice.value = '已标记为' + stateLabel(status) + '。'; undo.value = async () => { await commitFamily(data => { const item = data.coupons.find(c => c.id === id); if (!item || item.updatedAt !== expected.updatedAt || item.status !== status) throw Error('这张券已有新的修改，请在详情中调整。'); item.status = before.status; if (before.usedAt) item.usedAt = before.usedAt; else delete item.usedAt; item.updatedAt = new Date().toISOString(); }, { label: '已撤销状态修改' }); }; await closeDetails(); } }
async function undoAction() { if (!undo.value || busy.value) return; busy.value = 'undo'; try { await undo.value(); notice.value = '已撤销这次修改。'; undo.value = null; } catch (e) { error.value = e.message; } finally { busy.value = ''; } }
async function savePlan() { if (!isCouponDate(planDate.value)) { detailError.value = '请选择计划使用日期。'; return; } if (selected.value.expiresOn && planDate.value > selected.value.expiresOn) { detailError.value = '计划日期超过有效期，请换个日子。'; return; } if (await updateSelected(item => { item.plannedOn = planDate.value; item.status = 'booked'; }, '计划已放进家庭日历')) { arranging.value = false; notice.value = '已放进家庭日历，券的有效期仍会保留。'; undo.value = null; } }
async function deleteCoupon() { if (busy.value || readOnly.value) return; busy.value = 'delete'; try { await trashItem('coupons', selectedId.value); await closeDetails(); } catch (e) { detailError.value = e.message; } finally { busy.value = ''; } }
async function viewAttachment(attachment) { const request = ++imageRequest; if (imageViewer.value?.url) URL.revokeObjectURL(imageViewer.value.url); imageViewer.value = { attachment, url: '', loading: true, error: '' }; await nextTick(); if (!imageDialog.value.open) imageDialog.value.showModal(); try { const url = await readCouponImage(attachment.objectKey); if (request !== imageRequest || !imageViewer.value) { URL.revokeObjectURL(url); return; } imageViewer.value.url = url; } catch (e) { if (request === imageRequest && imageViewer.value) imageViewer.value.error = e.message; } finally { if (request === imageRequest && imageViewer.value) imageViewer.value.loading = false; } }
function closeImage() { imageRequest++; if (imageViewer.value?.url) URL.revokeObjectURL(imageViewer.value.url); imageDialog.value?.close(); imageViewer.value = null; }
async function applyRoute() { if (route.path !== '/life/coupons') return; if (route.query.new === '1') { await newCoupon(); await router.replace({ path: '/life/coupons', query: {} }); } else if (route.query.coupon) { const coupon = coupons.value.find(c => c.id === route.query.coupon); if (coupon && selectedId.value !== coupon.id) await openDetails(coupon, false); } }
watch(() => [route.query.coupon, route.query.new, coupons.value.length], applyRoute);
onMounted(() => { loadReminders(); applyRoute(); });
onActivated(applyRoute);
onDeactivated(() => { pauseEditor(); closeImage(); detailDialog.value?.close(); selectedId.value = ''; });
onBeforeRouteLeave(() => { if (busy.value) return false; if (editorVisible.value) pauseEditor(); closeImage(); detailDialog.value?.close(); selectedId.value = ''; });
onBeforeUnmount(() => { clearInterval(timer); releaseFiles(); closeImage(); });
</script>
